}

@keyframes fall {
  0% {
    transform: translateY(-10%);
    opacity: 1;
  }

  100% {
    transform: translateY(200%);
    opacity: 0;
  }
}

@media (max-width: 768px) {
  .matrix-column {
    font-size: 14px;
    line-height: 16px;
    width: 18px;
  }
}

@media (max-width: 480px) {
  .matrix-column {
    font-size: 12px;
    line-height: 14px;
    width: 15px;
  }
}

@keyframes rainbowShift {
  0% {
    color: linear-gradient(0deg, red, orange, yellow);
  }
  50% {
    color: linear-gradient(0deg, green, blue, indigo);
  }
  100% {
    color: linear-gradient(0deg, violet, red, orange);
  }
}

.matrix-column::before {
  animation: rainbowShift 5s infinite;
}
